const ow = await sdk.static.inspectWasm({view:"overview",startLine:1,lineCount:10});
const lf = await sdk.static.listFunctions({startIndex:50,limit:50});
const f11 = await sdk.static.inspectFunction({functionIndex:11,startLine:100,lineCount:100});
const cp = await sdk.prepareCheckpoint({hypothesis:"reach gameplay for dash test",steps:[{buttons:1,frames:10},{buttons:0,frames:30}],watches:[{name:"gamestate",address:18480,type:"u8",count:1},{name:"inputmirror",address:22,type:"u8",count:4}]});
let tid = cp.targets && cp.targets.length ? cp.targets[0].id : null;
let exp1=null;
if (tid) { exp1 = await sdk.runExperiment({hypothesis:"perturb gamestate byte, identical dash inputs, compare motion",checkpointId:cp.checkpointId,interventions:[{targetId:tid,value:2,hypothesis:"force state 2"}],steps:[{buttons:33,frames:10},{buttons:0,frames:50}],observations:{channels:["motion","timers","events","memory"],watches:[{name:"gamestate",address:18480,type:"u8",count:1}],captures:[]}}); }
const cp2id = exp1 ? exp1.checkpointId || cp.checkpointId : cp.checkpointId;
const expDash = await sdk.runExperiment({hypothesis:"dash input X+right vs control same checkpoint",checkpointId:cp.checkpointId,interventions:[],steps:[{buttons:33,frames:5},{buttons:0,frames:55}],observations:{channels:["motion","timers","events"],watches:[],captures:[]}});
return {overview:ow, funcCount:lf.totalFunctions||lf.functions?.length, f11excerpt:f11.lines?.slice(0,5), cpId:cp.checkpointId, targets:cp.targets, exp1:exp1?.summary||exp1, expDash:expDash?.summary||expDash, art1:exp1?.artifactId, artDash:expDash?.artifactId};

